using Microsoft.Extensions.ML;
using Microsoft.ML;
using Microsoft.ML.Data;
using TicketClassifier.Models;
using TicketClassifier.Services;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();
builder.Services.AddSingleton<ModelTrainingService>();

// Train the model at startup
var trainingService = new ModelTrainingService(
    LoggerFactory.Create(b => b.AddConsole())
        .CreateLogger<ModelTrainingService>());
trainingService.TrainAndEvaluate();

// Extract label names from the saved model
var mlContext = new MLContext();
var model = mlContext.Model.Load(trainingService.ModelPath, out var schema);
var transformer = model.Transform(mlContext.Data.LoadFromEnumerable(Array.Empty<TicketInput>()));
var scoreColumn = transformer.Schema["Score"];
var slotNames = new VBuffer<ReadOnlyMemory<char>>();
scoreColumn.GetSlotNames(ref slotNames);
var labels = slotNames.DenseValues().Select(v => v.ToString()).ToArray();
builder.Services.AddSingleton(new LabelRegistry(labels));

// Register pooled prediction engine (thread-safe for ASP.NET Core)
builder.Services.AddPredictionEnginePool<TicketInput, TicketPrediction>()
    .FromFile(trainingService.ModelPath);

var app = builder.Build();
app.MapControllers();
app.Run();

